CREATE OR REPLACE FUNCTION cartoquali_private.set_onboarding_operational_status(_cartorio_id uuid,_action text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='public','cartoquali_private','pg_temp' AS $$
DECLARE _caller uuid; _o public.cartorio_onboarding%rowtype; _check jsonb; _event text;
BEGIN
 IF auth.uid() IS NULL OR NOT cartoquali_private.is_platform_admin() THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501'; END IF;
 SELECT id INTO _caller FROM public.usuarios WHERE auth_user_id=auth.uid() AND status='ativo';
 SELECT * INTO _o FROM public.cartorio_onboarding WHERE cartorio_id=_cartorio_id FOR UPDATE;
 IF _o.id IS NULL THEN RAISE EXCEPTION 'onboarding_not_found' USING ERRCODE='P0002'; END IF;
 IF _action='activate' THEN
   SELECT cartoquali_private.get_onboarding_checklist(_cartorio_id) INTO _check;
   IF NOT coalesce((_check->>'complete')::boolean,false) THEN RAISE EXCEPTION 'incomplete_onboarding' USING ERRCODE='22023'; END IF;
   UPDATE public.cartorios SET status='ativo',updated_at=now() WHERE id=_cartorio_id;
   UPDATE public.pesquisas SET status='ativa',updated_at=now() WHERE id=_o.survey_id AND cartorio_id=_cartorio_id;
   UPDATE public.pontos_avaliacao SET status='ativo',updated_at=now() WHERE id=_o.point_id AND cartorio_id=_cartorio_id;
   UPDATE public.cartorio_onboarding SET status='ACTIVE',current_step=7,activated_at=coalesce(activated_at,now()),blocked_reason=NULL WHERE id=_o.id;
   _event:='CARTORIO_ACTIVATED';
 ELSIF _action='deactivate' THEN
   UPDATE public.cartorios SET status='inativo',updated_at=now() WHERE id=_cartorio_id;
   UPDATE public.cartorio_onboarding SET status='BLOCKED',blocked_reason='Desativado administrativamente' WHERE id=_o.id;
   _event:='CARTORIO_DEACTIVATED';
 ELSIF _action='reactivate' THEN
   IF _o.activated_at IS NULL THEN RAISE EXCEPTION 'never_activated' USING ERRCODE='22023'; END IF;
   UPDATE public.cartorios SET status='ativo',updated_at=now() WHERE id=_cartorio_id;
   UPDATE public.pesquisas SET status='ativa',updated_at=now() WHERE id=_o.survey_id;
   UPDATE public.pontos_avaliacao SET status='ativo',updated_at=now() WHERE id=_o.point_id;
   UPDATE public.cartorio_onboarding SET status='ACTIVE',blocked_reason=NULL WHERE id=_o.id;
   _event:='CARTORIO_REACTIVATED';
 ELSE RAISE EXCEPTION 'invalid_action' USING ERRCODE='22023'; END IF;
 INSERT INTO public.audit_logs(cartorio_id,user_id,action,entity,entity_id,metadata) VALUES(_cartorio_id,_caller,_event,'registry',_cartorio_id,'{}');
 RETURN jsonb_build_object('status',CASE WHEN _action='deactivate' THEN 'BLOCKED' ELSE 'ACTIVE' END);
END $$;
REVOKE ALL ON FUNCTION cartoquali_private.set_onboarding_operational_status(uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION cartoquali_private.set_onboarding_operational_status(uuid,text) TO service_role;

CREATE OR REPLACE FUNCTION public.get_quality_report(_current_start timestamptz,_current_end timestamptz,_previous_start timestamptz,_previous_end timestamptz,_point_id uuid DEFAULT NULL,_survey_id uuid DEFAULT NULL,_occurrence_status text DEFAULT NULL,_plan_status text DEFAULT NULL,_granularity text DEFAULT 'day') RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path='public','pg_temp' AS $$
DECLARE _result jsonb;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'unauthorized' USING ERRCODE='42501'; END IF;
 IF _current_start IS NULL OR _current_end IS NULL OR _previous_start IS NULL OR _previous_end IS NULL OR _current_start>=_current_end OR _previous_start>=_previous_end OR _granularity NOT IN ('day','week','month') OR (_occurrence_status IS NOT NULL AND _occurrence_status NOT IN ('nova','em_analise','em_tratamento','resolvida','encerrada')) OR (_plan_status IS NOT NULL AND _plan_status NOT IN ('planejado','em_andamento','concluido','cancelado')) THEN RAISE EXCEPTION 'invalid_request' USING ERRCODE='22023'; END IF;
 WITH current_evaluations AS MATERIALIZED (SELECT a.* FROM public.avaliacoes a WHERE NOT a.is_test AND a.created_at>=_current_start AND a.created_at<_current_end AND (_point_id IS NULL OR a.ponto_id=_point_id) AND (_survey_id IS NULL OR a.pesquisa_id=_survey_id)),previous_evaluations AS MATERIALIZED (SELECT a.* FROM public.avaliacoes a WHERE NOT a.is_test AND a.created_at>=_previous_start AND a.created_at<_previous_end AND (_point_id IS NULL OR a.ponto_id=_point_id) AND (_survey_id IS NULL OR a.pesquisa_id=_survey_id)),current_occurrences AS MATERIALIZED (SELECT o.* FROM public.ocorrencias_qualidade o WHERE o.data_abertura>=_current_start AND o.data_abertura<_current_end AND (_point_id IS NULL OR o.ponto_id=_point_id) AND (_survey_id IS NULL OR EXISTS(SELECT 1 FROM current_evaluations e WHERE e.id=o.avaliacao_id)) AND (_occurrence_status IS NULL OR o.status=_occurrence_status)),current_plans AS MATERIALIZED (SELECT p.* FROM public.planos_melhoria p WHERE p.created_at>=_current_start AND p.created_at<_current_end AND (_point_id IS NULL OR p.ponto_id=_point_id) AND (_survey_id IS NULL OR EXISTS(SELECT 1 FROM current_occurrences o JOIN current_evaluations e ON e.id=o.avaliacao_id WHERE o.id=p.ocorrencia_id)) AND (_plan_status IS NULL OR p.status=_plan_status)),summary AS (SELECT count(*)::int total,round(avg(nota_geral)::numeric,2) average,round((count(*) FILTER(WHERE nota_geral>=4)*100.0/nullif(count(*),0))::numeric,2) satisfaction,round((count(*) FILTER(WHERE nota_geral<=3)*100.0/nullif(count(*),0))::numeric,2) negative_rate,count(*) FILTER(WHERE nota_geral<=3)::int negative_count,count(*) FILTER(WHERE comentario IS NOT NULL AND btrim(comentario)<>'')::int comments,round((count(*) FILTER(WHERE atendimento_resolvido='sim')*100.0/nullif(count(*) FILTER(WHERE atendimento_resolvido IS NOT NULL),0))::numeric,2) resolution FROM current_evaluations),previous_summary AS (SELECT count(*)::int total,round(avg(nota_geral)::numeric,2) average,round((count(*) FILTER(WHERE nota_geral>=4)*100.0/nullif(count(*),0))::numeric,2) satisfaction,round((count(*) FILTER(WHERE nota_geral<=3)*100.0/nullif(count(*),0))::numeric,2) negative_rate,count(*) FILTER(WHERE nota_geral<=3)::int negative_count,round((count(*) FILTER(WHERE atendimento_resolvido='sim')*100.0/nullif(count(*) FILTER(WHERE atendimento_resolvido IS NOT NULL),0))::numeric,2) resolution FROM previous_evaluations),management AS (SELECT (SELECT count(*)::int FROM current_occurrences) occurrences_total,(SELECT count(*)::int FROM current_occurrences WHERE status IN ('resolvida','encerrada')) occurrences_resolved,(SELECT count(*)::int FROM current_plans) plans_total,(SELECT count(*)::int FROM current_plans WHERE status='concluido') plans_completed,(SELECT count(*)::int FROM current_plans WHERE status='em_andamento') plans_active,(SELECT count(*)::int FROM current_plans WHERE status NOT IN ('concluido','cancelado') AND prazo<(now() AT TIME ZONE 'America/Sao_Paulo')::date) plans_overdue),distribution AS (SELECT n.rating,count(e.id)::int count FROM generate_series(1,5)n(rating) LEFT JOIN current_evaluations e ON e.nota_geral=n.rating GROUP BY n.rating),series AS (SELECT date_trunc(_granularity,e.created_at AT TIME ZONE 'America/Sao_Paulo') bucket,count(*)::int total,round(avg(e.nota_geral)::numeric,2) average,round((count(*) FILTER(WHERE e.nota_geral>=4)*100.0/count(*))::numeric,2) satisfaction,round((count(*) FILTER(WHERE e.nota_geral<=3)*100.0/count(*))::numeric,2) negative_rate FROM current_evaluations e GROUP BY 1),point_performance AS (SELECT p.id,p.nome name,count(e.id)::int total,round(avg(e.nota_geral)::numeric,2) average,round((count(e.id) FILTER(WHERE e.nota_geral>=4)*100.0/nullif(count(e.id),0))::numeric,2) satisfaction,round((count(e.id) FILTER(WHERE e.nota_geral<=3)*100.0/nullif(count(e.id),0))::numeric,2) negative_rate FROM public.pontos_avaliacao p LEFT JOIN current_evaluations e ON e.ponto_id=p.id WHERE (_point_id IS NULL OR p.id=_point_id) AND (_survey_id IS NULL OR p.pesquisa_id=_survey_id) GROUP BY p.id,p.nome HAVING count(e.id)>0),current_dimension_values AS (SELECT lower(q.dimensao) dimension,CASE WHEN q.tipo IN ('stars','scale') AND jsonb_typeof(r.valor)='number' THEN (r.valor#>>'{}')::numeric WHEN q.tipo='yes_no' AND lower(coalesce(r.valor#>>'{}',r.resposta_texto,'')) IN ('sim','yes','true') THEN 5 WHEN q.tipo='yes_no' AND lower(coalesce(r.valor#>>'{}',r.resposta_texto,'')) IN ('parcialmente','partial') THEN 3 WHEN q.tipo='yes_no' AND lower(coalesce(r.valor#>>'{}',r.resposta_texto,'')) IN ('não','nao','no','false') THEN 1 END score FROM public.respostas r JOIN current_evaluations e ON e.id=r.avaliacao_id JOIN public.perguntas q ON q.id=r.pergunta_id AND q.pesquisa_id=e.pesquisa_id WHERE q.dimensao IN ('service','time','clarity','resolution','structure')),previous_dimension_values AS (SELECT lower(q.dimensao) dimension,CASE WHEN q.tipo IN ('stars','scale') AND jsonb_typeof(r.valor)='number' THEN (r.valor#>>'{}')::numeric WHEN q.tipo='yes_no' AND lower(coalesce(r.valor#>>'{}',r.resposta_texto,'')) IN ('sim','yes','true') THEN 5 WHEN q.tipo='yes_no' AND lower(coalesce(r.valor#>>'{}',r.resposta_texto,'')) IN ('parcialmente','partial') THEN 3 WHEN q.tipo='yes_no' AND lower(coalesce(r.valor#>>'{}',r.resposta_texto,'')) IN ('não','nao','no','false') THEN 1 END score FROM public.respostas r JOIN previous_evaluations e ON e.id=r.avaliacao_id JOIN public.perguntas q ON q.id=r.pergunta_id AND q.pesquisa_id=e.pesquisa_id WHERE q.dimensao IN ('service','time','clarity','resolution','structure')),dimension_keys AS (SELECT * FROM (VALUES('service','Atendimento'),('time','Tempo'),('clarity','Clareza'),('resolution','Resolutividade'),('structure','Estrutura'))d(key,label)),current_dimensions AS (SELECT dimension,count(score)::int responses,round((avg(score)/5*100)::numeric,2) index FROM current_dimension_values WHERE score BETWEEN 1 AND 5 GROUP BY dimension),previous_dimensions AS (SELECT dimension,count(score)::int responses,round((avg(score)/5*100)::numeric,2) index FROM previous_dimension_values WHERE score BETWEEN 1 AND 5 GROUP BY dimension),dimensions AS (SELECT d.key,d.label,coalesce(c.responses,0) responses,c.index,coalesce(p.responses,0) previous_responses,p.index previous_index FROM dimension_keys d LEFT JOIN current_dimensions c ON c.dimension=d.key LEFT JOIN previous_dimensions p ON p.dimension=d.key),evaluations_detail AS (SELECT e.id,e.created_at,e.nota_geral rating,e.atendimento_resolvido resolution,e.comentario comment,e.status,p.id point_id,p.nome point_name,s.id survey_id,s.nome survey_name FROM current_evaluations e JOIN public.pontos_avaliacao p ON p.id=e.ponto_id JOIN public.pesquisas s ON s.id=e.pesquisa_id ORDER BY e.created_at DESC LIMIT 5000),occurrences_detail AS (SELECT o.id,o.avaliacao_id evaluation_id,o.ponto_id,o.titulo title,o.categoria category,o.descricao description,o.prioridade priority,o.status,o.origem origin,o.prazo due_date,o.data_abertura opened_at,o.data_resolucao resolved_at,u.nome owner FROM current_occurrences o LEFT JOIN public.usuarios u ON u.id=o.responsavel_id ORDER BY o.data_abertura DESC LIMIT 2000),plans_detail AS (SELECT p.id,p.ocorrencia_id occurrence_id,p.ponto_id,p.dimensao dimension,p.titulo title,p.problema problem,p.objetivo objective,p.acao action,p.prioridade priority,p.prazo due_date,p.status,p.progresso progress,p.resultado_esperado expected_result,p.resultado result,p.observacao_resultado result_observation,p.indicador_nome indicator_name,p.indicador_antes indicator_before,p.indicador_depois indicator_after,p.concluido_em completed_at,p.created_at,p.updated_at,u.nome owner FROM current_plans p LEFT JOIN public.usuarios u ON u.id=p.responsavel_id ORDER BY p.created_at DESC LIMIT 2000),occurrence_groups AS (SELECT 'status' kind,status label,count(*)::int count FROM current_occurrences GROUP BY status UNION ALL SELECT 'category',categoria,count(*)::int FROM current_occurrences GROUP BY categoria UNION ALL SELECT 'priority',prioridade,count(*)::int FROM current_occurrences GROUP BY prioridade),plan_groups AS (SELECT status label,count(*)::int count FROM current_plans GROUP BY status),evidence_chain AS (SELECT e.id evaluation_id,e.created_at evaluation_date,e.nota_geral rating,e.comentario comment,p.nome point_name,o.id occurrence_id,o.titulo occurrence_title,o.categoria occurrence_category,o.status occurrence_status,o.descricao treatment,pl.id plan_id,pl.problema plan_problem,pl.acao plan_action,pl.prazo plan_due_date,pl.status plan_status,pl.resultado plan_result,u.nome responsible FROM current_evaluations e JOIN public.pontos_avaliacao p ON p.id=e.ponto_id LEFT JOIN public.ocorrencias_qualidade o ON o.avaliacao_id=e.id LEFT JOIN public.planos_melhoria pl ON pl.ocorrencia_id=o.id LEFT JOIN public.usuarios u ON u.id=pl.responsavel_id WHERE e.nota_geral<=3 OR o.id IS NOT NULL ORDER BY e.created_at DESC LIMIT 500),filters AS (SELECT (SELECT coalesce(jsonb_agg(jsonb_build_object('id',p.id,'name',p.nome,'surveyId',p.pesquisa_id) ORDER BY p.nome),'[]') FROM public.pontos_avaliacao p) points,(SELECT coalesce(jsonb_agg(jsonb_build_object('id',s.id,'name',s.nome) ORDER BY s.nome),'[]') FROM public.pesquisas s) surveys),registry AS (SELECT id,nome_fantasia trade_name,razao_social official_name FROM public.cartorios LIMIT 1) SELECT jsonb_build_object('registry',to_jsonb(r),'summary',to_jsonb(s),'previousSummary',to_jsonb(ps),'management',to_jsonb(m),'distribution',(SELECT coalesce(jsonb_agg(to_jsonb(d) ORDER BY d.rating),'[]') FROM distribution d),'series',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.bucket),'[]') FROM series x),'points',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.total DESC,x.name),'[]') FROM point_performance x),'dimensions',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.key),'[]') FROM dimensions x),'evaluations',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC),'[]') FROM evaluations_detail x),'occurrences',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.opened_at DESC),'[]') FROM occurrences_detail x),'plans',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC),'[]') FROM plans_detail x),'occurrenceGroups',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.kind,x.count DESC),'[]') FROM occurrence_groups x),'planGroups',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.count DESC),'[]') FROM plan_groups x),'evidence',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.evaluation_date DESC),'[]') FROM evidence_chain x),'filters',to_jsonb(f)) INTO _result FROM registry r CROSS JOIN summary s CROSS JOIN previous_summary ps CROSS JOIN management m CROSS JOIN filters f; RETURN coalesce(_result,'{}'::jsonb);
END $$;
REVOKE ALL ON FUNCTION public.get_quality_report(timestamptz,timestamptz,timestamptz,timestamptz,uuid,uuid,text,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_quality_report(timestamptz,timestamptz,timestamptz,timestamptz,uuid,uuid,text,text,text) TO authenticated,service_role;